// narrowServed is the desktop's zXl pass over the roster's served ids:
// no namespaced id, no placeholder, and a dated twin dropped when the
// plain id is served beside it. Family prefixes are not required — grok
// and mimo are relay models without one of the old prefixes.
function narrowServed(models) {
  const undated = new Set()
  for (const m of models) {
    const id = String(m.id ?? "").trim()
    if (id && !id.includes("/") && !DATED_SUFFIX.test(id)) undated.add(id)
  }
  const out = []
  const seen = new Set()
  for (const m of models) {
    const id = String(m.id ?? "").trim()
    if (!id || seen.has(id) || RESERVED_IDS.has(id) || id.includes("/")) continue
    if (DATED_SUFFIX.test(id) && undated.has(id.replace(DATED_SUFFIX, ""))) continue
    seen.add(id)
    out.push({ ...m, id })
  }
  return out
}

// selectModels is the list the desktop shows. A roster that names `served`
// is that list (catalog rows supply max_input_tokens when they have the
// id); an older roster with no such list falls back to the catalog the
// caller already narrowed. Duplicate ids the desktop collapses (its wun
// map) are dropped when the canonical id is present.
function selectModels(catalog, roster) {
  if (!roster?.served?.length) return catalog
  const byId = new Map(catalog.map((m) => [String(m.id ?? "").toLowerCase().trim(), m]))
  const items = roster.served.map((id) => {
    const cat = byId.get(id)
    return cat ? { ...cat, id } : { id, max_input_tokens: 0 }
  })
  const narrowed = narrowServed(items)
  const present = new Set(narrowed.map((m) => m.id))
  return narrowed.filter((m) => {
    const target = relayDuplicates[m.id]
    return !target || !present.has(target)
  })
}

// listedCatalog turns one catalog and the roster beside it into the models
// magpie lists. When the roster names `served`, that is the list (the
// desktop's own); otherwise the catalog already narrowed. Withdrawn ids
// are dropped, and the selectors this plugin ships are published beside
// the relay's own id (Kimi's "kimi-code/k3" beside "kimi-k3", DeepSeek's
// "deepseek-v4.1-flash" beside "deepseek-flash"). null when nothing survives.
function listedCatalog(parsed, roster) {
  const kept = withoutWithdrawn(selectModels(parsed, roster), roster)
  if (!kept.length) return null
  const listed = Object.fromEntries(kept.map((m) => [m.id, runtimeModel(m, roster)]))
  for (const [id, model] of Object.entries(listed)) {
    for (const alias of selectorAliasesFor(id)) {
      if (!listed[alias]) listed[alias] = { ...model, id: alias, name: alias, api: { ...model.api, id: alias } }
    }
  }
  const gone = withdrawnSet(roster)
  if (!gone) return listed
  return Object.fromEntries(Object.entries(listed).filter(([id]) => !gone.has(id.toLowerCase().trim())))
}

// fallbackCatalog is the catalog the account's own record keeps, used when the
// relay cannot be asked. An empty list is not a cosmetic loss: magpie reads a
// provider with no models as "no endpoint configured" and refuses every call
// in its own routing, with a 502, before the plugin's fetch is ever reached.
function fallbackCatalog(provider, auth) {
  try {
    const raw = auth?.models ? JSON.parse(auth.models) : null
    if (raw) {
      let roster = null
      try {
        roster = auth?.roster ? parseRoster(JSON.parse(auth.roster)) : null
      } catch {
        roster = null
      }
      const listed = listedCatalog(parseModels(raw), roster)
      if (listed) return listed
    }
  } catch {}
  return provider.models
}

// runtimeModel is one catalog entry as OpenCode lists it: on Anthropic's// wire for Claude, DeepSeek, GLM, Kimi and Gemini, OpenAI Responses for GPT,
// with the reasoning ladder the roster or the family declares. The roster's
// shape decides: the levels it lists, narrowed onto the rungs the family
// takes; the family's own when a shape is named without a list; nothing for
// an entry that only carries metadata, whose form the relay hasn't declared —
// advertising one would invite a request the relay refuses. Every relay
// model takes image input, as the official built-in provider declares.
function runtimeModel(m, roster) {
  const family = familyOf(String(m.id).toLowerCase())
  const spec = roster ? specOf(roster, m.id) : null
  const context = Math.max(Number(m.max_input_tokens ?? 0), Number(spec?.contextWindow ?? 0))
  let efforts = spec ? spec.effort.filter((level) => effortSupported(family, level)) : []
  if (!efforts.length && (!spec || thinkingAdaptive(roster, m.id).known)) efforts = familyEfforts(family)
  const npm = family === "codex" ? OPENAI : ANTHROPIC
  return {
    id: m.id,
    providerID: ID,
    name: spec?.label || m.id,
    api: { id: m.id, url: RELAY() + "/v1", npm },
    status: "active",
    headers: {},
    options: {},
    cost: { input: 0, output: 0, cache: { read: 0, write: 0 } },
    limit: { context, output: Number(spec?.maxOutput ?? 0) },
    capabilities: {
      temperature: true,
      reasoning: efforts.length > 0,
      attachment: true,
      toolcall: true,
      input: { text: true, image: true, audio: false, video: false, pdf: false },
      output: { text: true, image: false, audio: false, video: false, pdf: false },
      interleaved: false,
    },
    release_date: "",
    variants: Object.fromEntries(efforts.map((e) => [e, { reasoningEffort: e }])),
  }
}

